const opt = (vals) => vals.map(([value, label], i) => ({ value, label, displayOrder: i }));
const text = (name, label) => ({ name, label, type: 'string', fieldType: 'text' });
const area = (name, label) => ({ name, label, type: 'string', fieldType: 'textarea' });
const num = (name, label) => ({ name, label, type: 'number', fieldType: 'number' });
const sel = (name, label, vals) => ({ name, label, type: 'enumeration', fieldType: 'select', options: opt(vals) });
const bool = (name, label) => ({ name, label, type: 'bool', fieldType: 'booleancheckbox', options: opt([['true', 'Yes'], ['false', 'No']]) });
const CH = [['landing_page', 'Landing page (Google Search)'], ['meta_lead_ads', 'Meta Lead Ads'], ['whatsapp', 'WhatsApp (Snapchat CTWA)']];
const ASSETS = [['cb_tahlia_khobar', 'عمارة تجارية - التحلية - الخبر'], ['cb_nuzha_dammam', 'عمارة تجارية - النزهة - الدمام'], ['rb_taiba_dammam', 'عمارة سكنية - طيبة - الدمام'], ['rb_jalawiyah_dammam', 'عمارة سكنية - الجلوية - الدمام'], ['villa_aqrabiyah_khobar', 'فيلا - العقربية - الخبر'], ['villa_taiba_dammam', 'فيلا - طيبة - الدمام'], ['villa_fayhaa_dammam', 'فيلا - الفيحاء - الدمام'], ['villa_nakheel_dammam', 'فيلا - النخيل - الدمام'], ['land_muraikabat_1', 'أرض تجارية - المريكبات 1'], ['land_muraikabat_2', 'أرض تجارية - المريكبات 2'], ['apt_nour_dammam', 'شقة - النور - الدمام'], ['type_villa', 'فيلا (بدون تحديد)'], ['type_apartment', 'شقة (بدون تحديد)'], ['type_residential_building', 'عمارة سكنية (بدون تحديد)'], ['type_commercial_building', 'عمارة تجارية (بدون تحديد)'], ['type_commercial_land', 'أرض تجارية (بدون تحديد)'], ['unknown', 'غير محدد']];
const contact = [
  text('fana_lead_key', 'FANA Lead Key'),
  sel('fana_lead_source', 'FANA Lead Source', CH),
  sel('preferred_contact_method', 'Preferred Contact Method', [['call', 'Call'], ['whatsapp', 'WhatsApp'], ['email', 'Email']]),
  sel('contact_consent', 'Contact Consent', [['granted', 'Granted'], ['denied', 'Denied']]),
];
const deal = [
  text('fana_lead_key', 'FANA Lead Key'),
  sel('interested_asset', 'Interested Asset', ASSETS),
  num('budget_min', 'Budget Min (SAR)'), num('budget_max', 'Budget Max (SAR)'),
  num('qualification_score', 'Qualification Score'),
  sel('qualification_status', 'Qualification Status', [['in_qualification', 'In qualification'], ['qualified', 'Qualified'], ['needs_review', 'Needs human review'], ['handoff_requested', 'Asked for a person'], ['disqualified', 'Disqualified']]),
  sel('sales_priority', 'Sales Priority', [['P1', 'P1 - Hot, call now'], ['P2', 'P2 - Follow up'], ['P3', 'P3 - Nurture'], ['Disqualified', 'Disqualified']]),
  sel('purchase_timeline', 'Purchase Timeline', [['this_auction', 'This auction'], ['within_3_months', 'Within 3 months'], ['later', 'Later'], ['unknown', 'Unknown']]),
  sel('financial_readiness', 'Financial Readiness', [['cash', 'Cash ready'], ['financing_approved', 'Financing approved'], ['financing_in_progress', 'Financing in progress'], ['financing_needed', 'Needs financing'], ['unknown', 'Unknown']]),
  sel('lead_channel', 'Lead Channel', CH),
  bool('sales_handoff_ready', 'Sales Handoff Ready'),
  area('priority_reason', 'Priority Reason'),
  area('ai_summary', 'AI Summary'),
];
return [
  ...contact.map(p => ({ json: { objectType: 'contacts', body: { ...p, groupName: 'contactinformation' } } })),
  ...deal.map(p => ({ json: { objectType: 'deals', body: { ...p, groupName: 'dealinformation' } } })),
];

const defs = $('Property Definitions').all();
const rows = $input.all().map((r, i) => {
  const d = defs[i].json;
  const code = r.json.statusCode;
  const status = code === 201 ? 'created' : code === 409 ? 'already_exists' : 'error';
  return { object: d.objectType, property: d.body.name, status, code, message: status === 'error' ? JSON.stringify(r.json.body).slice(0, 300) : '' };
});
return [{ json: { properties: rows, errors: rows.filter(r => r.status === 'error').length } }];

const pipes = $input.first().json.results || [];
const pipe = pipes.find(p => p.id === 'default') || pipes[0];
const wanted = [['New Lead', '0.1'], ['AI Qualifying', '0.1'], ['Follow-up (P2)', '0.3'], ['Sales Ready (P1)', '0.5'], ['Contacted', '0.6'], ['Registered to Bid', '0.8'], ['Closed Won', '1.0', true], ['Closed Lost', '0.0', true]];
const existing = (pipe.stages || []).map(s => s.label);
const alreadyDone = wanted.every(([l]) => existing.includes(l));
const stages = wanted.map(([label, probability, closed], i) => ({ label, displayOrder: i, metadata: closed ? { probability, isClosed: 'true' } : { probability } }));
return [{ json: { pipeline_id: pipe.id, already_done: alreadyDone, body: { label: 'FANA Auction Pipeline', displayOrder: 0, stages } } }];

const r = $input.first().json;
const stages = ((r.body || {}).stages || []).map(s => ({ id: s.id, label: s.label }));
return [{ json: { properties: $('Summarize Properties').first().json, pipeline_status: r.statusCode, pipeline_error: r.statusCode >= 300 ? JSON.stringify(r.body).slice(0, 400) : '', stages } }];
